package com.xemantic.typescript.tsgo

import com.xemantic.kotlin.test.assert
import com.xemantic.typescript.tsgo.go.regexp.mustCompile
import com.xemantic.typescript.tsgo.go.regexp.translateRe2
import kotlin.test.Test

/**
 * The `regexp` shim against real Go (go1.27.1): every pattern below exercises one place where
 * RE2 and Java syntax or semantics disagree (literal `{`, `[` inside a class, `&&`, POSIX classes,
 * `$` = end of text, `.` and `\r`, `\s` and `\x0B`, `(?P<name>`, `\Q…\E`, `\z`/`\A`), run over every
 * input with `MatchString`, `FindStringSubmatch`, `ReplaceAllString` (Go's `$` template rules) and
 * `ReplaceAllStringFunc`. Regenerate with the throwaway Go program in the round's scratch.
 */
class RegexpOracleTest {

    private class R(val pat: Int, val input: Int, val match: Boolean, val sub: List<String>?, val replaced: List<String>)

    @Test
    fun `translated patterns behave like Go RE2`() {
        val mismatches = ArrayList<String>()
        for (r in ROWS) {
            val re = mustCompile(PATS[r.pat])
            val input = INPUTS[r.input]
            val where = "pattern ${PATS[r.pat]} -> ${translateRe2(PATS[r.pat])} on input #${r.input}"
            if (re.matchString(input) != r.match) mismatches += "$where: MatchString"
            val sub = re.findStringSubmatch(input)
            val got = if (sub.isNil) null else (0 until sub.len).map { sub[it] }
            if (got != r.sub) mismatches += "$where: FindStringSubmatch $got"
            for ((t, tmpl) in TMPLS.withIndex()) {
                val rep = re.replaceAllString(input, tmpl)
                if (rep != r.replaced[t]) mismatches += "$where: ReplaceAllString($tmpl) = $rep"
            }
            if (re.replaceAllStringFunc(input) { "<$it>" } != r.replaced.last()) mismatches += "$where: ReplaceAllStringFunc"
        }
        assert(mismatches.isEmpty())
    }

    @Test
    fun `String returns the Go source of the pattern`() {
        assert(mustCompile("{(\\d+)}").string() == "{(\\d+)}")
    }

