        val PATS: List<String> = listOf("{(\u005cd+)}", "a{", "a{,2}", "x{2}", "a{2,}b", "[]a]+", "[[:alpha:]]+", "[[:^digit:]]+", "[a[b]+", "a\u0024", "\u005cs+", "(?P<n>\u005cd+)-(?P<m>\u005cw+)", "a.c", "(?s)a.c", "\u005cQa.b\u005cE", "[a&&b]+", "^_+(\u005cD)", "_\u0024", "\u005c\u005c.", "_+", "}x", "\u005cz", "\u005cAa", "(?i)abc", "[^\u005cs]+", "x{1}{", "(a)|(b)")
